WITH promo_channels AS ( SELECT p.p_promo_sk, p.p_promo_name, p.p_cost, channel_name, channel_flag FROM promotion p CROSS JOIN UNNEST( ARRAY['TV','Email','Radio','Press','Catalog','Dmail','Event','Details'], ARRAY[p.p_channel_tv, p.p_channel_email, p.p_channel_radio, p.p_channel_press, p.p_channel_catalog, p.p_channel_dmail, p.p_channel_event, p.p_channel_details] ) AS t (channel_name, channel_flag) WHERE channel_flag IS NOT NULL ), channel_sales AS ( SELECT pc.channel_name, w.w_state, COUNT(DISTINCT pc.p_promo_sk) AS promo_cnt, SUM(ws.ws_sales_price * ws.ws_quantity) AS total_sales, AVG(ws.ws_ext_discount_amt) AS avg_discount, SUM(pc.p_cost) AS total_promo_cost FROM promo_channels pc JOIN web_sales ws ON ws.ws_promo_sk = pc.p_promo_sk JOIN warehouse w ON ws.ws_warehouse_sk = w.w_warehouse_sk GROUP BY pc.channel_name, w.w_state ) SELECT channel_name, w_state, promo_cnt, total_sales, avg_discount, total_promo_cost, CASE WHEN total_promo_cost > 0 THEN ROUND(total_sales / total_promo_cost, 2) ELSE NULL END AS sales_per_cost, RANK() OVER (ORDER BY CASE WHEN total_promo_cost > 0 THEN total_sales / total_promo_cost ELSE NULL END DESC) AS sales_per_cost_rank FROM channel_sales ORDER BY sales_per_cost_rank
